// Filter for approved items
const items = $input.all();

const approved = items.filter(item => {
    const row = item.json;
    const autoApply = String(row.auto_apply_suggested || '').trim();
    const applied = String(row.Applied || '').trim();

    return (autoApply === 'Yes') && (applied !== 'Yes' && applied !== 'Applied');
});

console.log(`Found ${approved.length} changes to apply`);
return approved;

// Build Google Ads API mutation - FIXED with raw_recommendation fallback
const row = $json;

console.log('=== Processing Row ===');
console.log('Row number:', row.row_number);
console.log('Entity:', row.entity_name);
console.log('Entity ID (direct):', row.entity_id);
console.log('Campaign ID (direct):', row.campaign_id);
console.log('Ad Group ID (direct):', row.ad_group_id);
console.log('Change type (direct):', row.change_type);

// Extract account ID (remove dashes)
const accountId = String(row.account_id || '865-640-6794').replace(/-/g, '');
console.log('Account ID:', accountId);

// Parse raw_recommendation to get missing fields
let rawRec = null;
if (row.raw_recommendation) {
    try {
        rawRec = typeof row.raw_recommendation === 'string'
            ? JSON.parse(row.raw_recommendation)
            : row.raw_recommendation;
        console.log('✓ Parsed raw_recommendation successfully');
    } catch (e) {
        console.log('✗ Could not parse raw_recommendation:', e.message);
    }
}

// Get values with fallback to raw_recommendation
const changeType = String(row.change_type || (rawRec && rawRec.type) || (rawRec && rawRec.change_type) || '').toUpperCase().trim();
const campaignId = row.campaign_id || (rawRec && rawRec.campaign_id) || '';
const adGroupId = row.ad_group_id || (rawRec && rawRec.ad_group_id) || '';
const matchType = row.match_type || (rawRec && rawRec.match_type) || '';

console.log('Final change_type:', changeType);
console.log('Final campaign_id:', campaignId);
console.log('Final ad_group_id:', adGroupId);
console.log('Final match_type:', matchType);

let requestBody = null;
let endpoint = '';
let skipReason = null;

// ===== PAUSE KEYWORD =====
if (changeType === 'PAUSE_KEYWORD') {
    console.log('✓ PAUSE_KEYWORD detected');

    // Validate we have criterion_id
    if (!row.entity_id || row.entity_id === 'N/A' || row.entity_id === row.entity_name) {
        skipReason = `Cannot pause keyword without valid criterion ID. Got: ${row.entity_id}`;
        console.log('✗', skipReason);
    } else if (!adGroupId) {
        skipReason = `Cannot pause keyword without ad_group_id. Got: ${adGroupId}`;
        console.log('✗', skipReason);
    } else {
        // Build resource name: customers/{customer_id}/adGroupCriteria/{ad_group_id}~{criterion_id}
        const resourceName = `customers/${accountId}/adGroupCriteria/${adGroupId}~${row.entity_id}`;

        requestBody = {
            operations: [{
                updateMask: "status",
                update: {
                    resourceName: resourceName,
                    status: "PAUSED"
                }
            }]
        };
        endpoint = `https://googleads.googleapis.com/v22/customers/${accountId}/adGroupCriteria:mutate`;
        console.log('✓ Built PAUSE_KEYWORD mutation');
        console.log('  Resource:', resourceName);
    }
}

// ===== ADD NEGATIVE KEYWORD =====
else if (changeType === 'ADD_NEGATIVE_KEYWORD' || changeType === 'NEGATIVE_KEYWORD') {
    console.log('✓ ADD_NEGATIVE_KEYWORD detected');

    if (!row.entity_name) {
        skipReason = 'Cannot add negative keyword without keyword text';
        console.log('✗', skipReason);
    } else if (!campaignId && !adGroupId) {
        skipReason = 'Cannot add negative keyword without campaign_id or ad_group_id';
        console.log('✗', skipReason);
    } else {
        // Determine if campaign-level or ad group-level negative
        const isCampaignLevel = !!campaignId && !adGroupId;

        if (isCampaignLevel) {
            // Campaign-level negative keyword
            requestBody = {
                operations: [{
                    create: {
                        campaign: `customers/${accountId}/campaigns/${campaignId}`,
                        keyword: {
                            text: row.entity_name,
                            matchType: "BROAD"
                        },
                        type: "KEYWORD"
                    }
                }]
            };
            endpoint = `https://googleads.googleapis.com/v22/customers/${accountId}/campaignCriteria:mutate`;
            console.log('✓ Built campaign-level NEGATIVE_KEYWORD mutation');
        } else {
            // Ad group-level negative keyword
            requestBody = {
                operations: [{
                    create: {
                        adGroup: `customers/${accountId}/adGroups/${adGroupId}`,
                        keyword: {
                            text: row.entity_name,
                            matchType: "BROAD"
                        },
                        type: "KEYWORD",
                        negative: true
                    }
                }]
            };
            endpoint = `https://googleads.googleapis.com/v22/customers/${accountId}/adGroupCriteria:mutate`;
            console.log('✓ Built ad group-level NEGATIVE_KEYWORD mutation');
        }
        console.log('  Keyword:', row.entity_name);
    }
}

// ===== PAUSE CAMPAIGN =====
else if (changeType === 'PAUSE_CAMPAIGN') {
    console.log('✓ PAUSE_CAMPAIGN detected');

    const finalCampaignId = campaignId || row.entity_id;
    if (!finalCampaignId) {
        skipReason = 'Cannot pause campaign without campaign_id or entity_id';
        console.log('✗', skipReason);
    } else {
        const resourceName = `customers/${accountId}/campaigns/${finalCampaignId}`;

        requestBody = {
            operations: [{
                updateMask: "status",
                update: {
                    resourceName: resourceName,
                    status: "PAUSED"
                }
            }]
        };
        endpoint = `https://googleads.googleapis.com/v22/customers/${accountId}/campaigns:mutate`;
        console.log('✓ Built PAUSE_CAMPAIGN mutation');
        console.log('  Resource:', resourceName);
    }
}

// ===== PAUSE AD =====
else if (changeType === 'PAUSE_AD') {
    console.log('✓ PAUSE_AD detected');

    if (!row.entity_id || row.entity_id === 'N/A') {
        skipReason = 'Cannot pause ad without valid entity_id (ad ID)';
        console.log('✗', skipReason);
    } else if (!adGroupId) {
        skipReason = 'Cannot pause ad without ad_group_id';
        console.log('✗', skipReason);
    } else {
        // Resource name: customers/{customer_id}/adGroupAds/{ad_group_id}~{ad_id}
        const resourceName = `customers/${accountId}/adGroupAds/${adGroupId}~${row.entity_id}`;

        requestBody = {
            operations: [{
                updateMask: "status",
                update: {
                    resourceName: resourceName,
                    status: "PAUSED"
                }
            }]
        };
        endpoint = `https://googleads.googleapis.com/v22/customers/${accountId}/adGroupAds:mutate`;
        console.log('✓ Built PAUSE_AD mutation');
        console.log('  Resource:', resourceName);
    }
}

// ===== ADJUST BID =====
else if (changeType === 'ADJUST_BID' || changeType.includes('BID')) {
    console.log('✓ ADJUST_BID detected');

    if (!row.entity_id || !adGroupId) {
        skipReason = 'Cannot adjust bid without entity_id (criterion_id) and ad_group_id';
        console.log('✗', skipReason);
    } else if (!row.new_value) {
        skipReason = 'Cannot adjust bid without new_value';
        console.log('✗', skipReason);
    } else {
        // Convert dollars to micros (1 USD = 1,000,000 micros)
        const newBidMicros = Math.round(parseFloat(row.new_value) * 1000000);
        const resourceName = `customers/${accountId}/adGroupCriteria/${adGroupId}~${row.entity_id}`;

        requestBody = {
            operations: [{
                updateMask: "cpcBidMicros",
                update: {
                    resourceName: resourceName,
                    cpcBidMicros: newBidMicros
                }
            }]
        };
        endpoint = `https://googleads.googleapis.com/v22/customers/${accountId}/adGroupCriteria:mutate`;
        console.log('✓ Built ADJUST_BID mutation');
        console.log('  New bid:', `$${row.new_value} (${newBidMicros} micros)`);
    }
}

// ===== ADD KEYWORD (from converting search terms) =====
else if (changeType === 'ADD_KEYWORD') {
    console.log('✓ ADD_KEYWORD detected');

    if (!row.entity_name) {
        skipReason = 'Cannot add keyword without keyword text (entity_name)';
        console.log('✗', skipReason);
    } else if (!adGroupId) {
        skipReason = 'Cannot add keyword without ad_group_id';
        console.log('✗', skipReason);
    } else {
        // Use extracted match type or default to EXACT
        const finalMatchType = matchType ? String(matchType).toUpperCase() : 'EXACT';

        // Build the create operation for new keyword
        requestBody = {
            operations: [{
                create: {
                    adGroup: `customers/${accountId}/adGroups/${adGroupId}`,
                    status: "ENABLED",
                    keyword: {
                        text: row.entity_name,
                        matchType: finalMatchType
                    },
                    type: "KEYWORD"
                }
            }]
        };
        endpoint = `https://googleads.googleapis.com/v22/customers/${accountId}/adGroupCriteria:mutate`;
        console.log('✓ Built ADD_KEYWORD mutation');
        console.log('  Keyword:', row.entity_name);
        console.log('  Match type:', finalMatchType);
        console.log('  Ad Group ID:', adGroupId);
    }
}

// ===== UNKNOWN CHANGE TYPE =====
else {
    skipReason = `Unsupported change type: ${changeType}`;
    console.log('✗', skipReason);
}

// Return result
if (skipReason) {
    console.log('⚠ Skipping this item');
    return {
        json: {
            ...row,
            error: skipReason,
            skip: true,
            has_error: true
        }
    };
}

console.log('✓ Mutation ready');
console.log('  Endpoint:', endpoint);

return {
    json: {
        ...row,
        api_endpoint: endpoint,
        api_body: requestBody,
        skip: false,
        has_error: false
    }
};

// Skip items with errors - WITH EXTENSIVE LOGGING
const items = $input.all();

console.log('=== SKIP INVALID ITEMS ===');
console.log(`Total items received: ${items.length}`);

items.forEach((item, index) => {
    console.log(`\nItem ${index + 1}:`);
    console.log(`  Row: ${item.json.row_number}`);
    console.log(`  Entity: ${item.json.entity_name}`);
    console.log(`  Skip: ${item.json.skip}`);
    console.log(`  Has error: ${item.json.has_error}`);
    if (item.json.error) {
        console.log(`  Error: ${item.json.error}`);
    }
});

const valid = items.filter(item => {
    const shouldSkip = item.json.skip === true;
    console.log(`Row ${item.json.row_number}: skip=${item.json.skip}, will ${shouldSkip ? 'SKIP' : 'KEEP'}`);
    return !shouldSkip;
});

console.log(`\n✓ RESULT: ${valid.length} valid items out of ${items.length} total`);

if (valid.length === 0) {
    throw new Error('NO VALID ITEMS! All items were skipped. Check the logs above for reasons.');
}

console.log(`✓ ${valid.length} items will proceed to Apply to Google Ads`);
valid.forEach(item => {
    console.log(`  - Row ${item.json.row_number}: ${item.json.entity_name}`);
});

return valid;
